def test_all_blank_closes_give_no_rows() -> None:
    rows = [RawRow(date="2024-01-01", ticker="ACME", close=None)]

    assert validate_rows(rows) == []


def test_zero_and_negative_closes_are_dropped() -> None:
    rows = [
        RawRow(date="2024-01-01", ticker="ACME", close=0.0),
        RawRow(date="2024-01-01", ticker="BOLT", close=-2.5),
        RawRow(date="2024-01-01", ticker="CORE", close=0.01),
    ]

    assert validate_rows(rows) == [RawRow(date="2024-01-01", ticker="CORE", close=0.01)]


def test_later_duplicate_replaces_earlier() -> None:
    rows = [
        RawRow(date="2024-01-01", ticker="ACME", close=1.0),
        RawRow(date="2024-01-01", ticker="ACME", close=2.0),
        RawRow(date="2024-01-01", ticker="ACME", close=3.0),
    ]

    assert validate_rows(rows) == [RawRow(date="2024-01-01", ticker="ACME", close=3.0)]


def test_unusable_later_duplicate_does_not_replace_usable_row() -> None:
    rows = [
        RawRow(date="2024-01-01", ticker="ACME", close=4.0),
        RawRow(date="2024-01-01", ticker="ACME", close=None),
    ]

    assert validate_rows(rows) == [RawRow(date="2024-01-01", ticker="ACME", close=4.0)]


def test_missing_requested_ticker_raises_key_error_naming_it() -> None:
    rows = [
        RawRow(date="2024-01-01", ticker="ACME", close=1.0),
        RawRow(date="2024-01-01", ticker="BOLT", close=0.0),
    ]

    with pytest.raises(KeyError, match="BOLT"):
        validate_rows(rows, ["ACME", "BOLT"])


def test_requested_tickers_present_keep_all_rows() -> None:
    rows = [
        RawRow(date="2024-01-01", ticker="ACME", close=1.0),
        RawRow(date="2024-01-01", ticker="BOLT", close=2.0),
    ]

    assert validate_rows(rows, ["BOLT"]) == rows

